export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/** Includes a removed membership so a re-invite can restore the same row. */
export async function findMembership(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)),
    )
    .get();
  return row ? toMember(row) : null;
}

/**
 * Puts a former member back on the same row: new role, the acceptance time as
 * the join date, and the sender of the new invitation as the inviter.
 */
export async function reactivateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  joinedAt: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(),
      role,
      status: "active",
      invitedBy,
      joinedAt,
      updatedAt: joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

