import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member, Role } from "@/types/member";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Refuses the whole batch before any row is written. Addresses are compared
 * without regard to letter case. A current member or a still-pending invite
 * blocks the address; a former member, or an expired or revoked invite, does not.
 */
async function assertInvitesAreNew(
  orgId: InviteMembersInput["orgId"],
  invites: readonly { email: string; role: Role }[],
): Promise<readonly { email: string; role: Role }[]> {
  const normalized = invites.map((invite) => ({
    email: normalizeEmail(invite.email),
    role: invite.role,
  }));

  const seen = new Set<string>();
  for (const invite of normalized) {
    if (seen.has(invite.email)) {
      throw new Error(
        `Cannot invite ${invite.email} twice in the same batch`,
      );
    }
    seen.add(invite.email);
  }

  const members = await memberRepo.listActiveMemberEmails(orgId);
  const memberEmails = new Set(
    members.map((member) => normalizeEmail(member.email)),
  );

  for (const invite of normalized) {
    if (memberEmails.has(invite.email)) {
      throw new Error(
        `${invite.email} is already a member of this workspace`,
      );
    }
    const pending = await invitationRepo.findPendingInvitationByEmail(
      orgId,
      invite.email,
    );
    if (pending) {
      throw new Error(
        `${invite.email} already has a pending invitation`,
      );
    }
  }

  return normalized;
}

