/**
 * Stops sessions from opening on a workspace the user can no longer use.
 * Only sessions whose default is this workspace move, and each one moves to
 * another workspace that user still belongs to. Every other session stays.
 */
export async function releaseDefaultOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<void> {
  const affected = await sessionRepo.listSessionsForActiveOrg(orgId, userId);
  for (const session of affected) {
    const orgs = await orgRepo.listOrgsForUser(session.userId);
    const next = orgs.find((org) => org.id !== orgId) ?? null;
    await sessionRepo.setActiveOrg(session.id, next?.id ?? null);
  }
}

/** Records the default workspace for the session identified by the raw cookie. */
export async function rememberActiveOrg(
  token: string,
  orgId: OrgId,
): Promise<void> {
  await sessionRepo.setActiveOrgByTokenHash(hashToken(token), orgId);
}

