input.new_string:
export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  const tokenHash = hashToken(token);
  const principal = await sessionRepo.findSessionByTokenHash(tokenHash);
  if (principal === null || principal.activeOrgId === null) return principal;

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  if (orgs.some((org) => org.id === principal.activeOrgId)) return principal;

  const next = orgs.find((org) => org.id !== principal.activeOrgId) ?? null;
  await sessionRepo.setActiveOrgByTokenHash(tokenHash, next?.id ?? null);
  return { ...principal, activeOrgId: next?.id ?? null };
}

