  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }

  const now = toIsoTimestamp(new Date());
  const holdsSeat =
    previous.revokedAt === null && previous.expiresAt > now;

  // A still-pending invite is holding the seat the replacement needs.
  if (holdsSeat) {
    await invitationRepo.revokeInvitation(actor.orgId, invitationId);
    await usageRepo.recomputeUsage(actor.orgId);
  }

  const replacement = await inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: previous.role as InviteMemberInput["role"],
  });

  if (!holdsSeat && previous.revokedAt === null) {
    await invitationRepo.revokeInvitation(actor.orgId, invitationId);
  }

  return replacement;
}

