 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invitations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation } from "./_mappers";
10→import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * A pending invitation has not been accepted, revoked, or expired. Only those
 * rows hold a seat. Expiry is measured in whole days from the moment the
 * invitation was sent (or re-sent).
20→ */
function pendingInvitationPredicate(orgId: OrgId, now: IsoTimestamp) {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, now),
  );
}

30→export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * MS_PER_DAY),
  );
40→
  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email.trim().toLowerCase(),
      role: input.role,
      invitedBy,
      tokenHash,
50→      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
60→}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
70→  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

export async function findInvitationById(
  orgId: OrgId,
80→  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
90→    )
    .get();
  return row ? toInvitation(row) : null;
}

/** Case-insensitive match against invitations that still hold a seat. */
export async function findPendingInvitationByEmail(
  orgId: OrgId,
  email: string,
): Promise<Invitation | null> {
100→  const normalized = email.trim().toLowerCase();
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        pendingInvitationPredicate(orgId, toIsoTimestamp(new Date())),
        sql`lower(${invitations.email}) = ${normalized}`,
      ),
    )
110→    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
120→    .where(pendingInvitationPredicate(orgId, toIsoTimestamp(new Date())))
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

