export async function releaseDefaultOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<void> {
  const affected = await sessionRepo.listSessionsForActiveOrg(orgId, userId);
  for (const session of affected) {
    const orgs = await orgRepo.listOrgsForUser(session.userId);
    const next = orgs.find((org) => org.id !== orgId) ?? null;
    await sessionRepo.setActiveOrg(session.id, next?.id ?? null);
